/** Resolve supported configuration preferences outside Compose (widgets, notifications, workers). */
fun sbResolveAppLocale(context: Context, appLocales: List<Locale>, fallback: Locale = Locale.GERMAN): Locale {
    val locales = context.resources.configuration.locales
    return locales.toLanguageTags().split(',').filter { it.isNotEmpty() }.map(Locale::forLanguageTag)
        .firstOrNull { candidate -> appLocales.any { it.language == candidate.language } } ?: fallback
}

/** Mode the current screen is drawn in; SebaroAppTheme provides it. */
val LocalSebaroDarkTheme = staticCompositionLocalOf<Boolean?> { null }

/** True when the screen draws dark; outside SebaroAppTheme it compares the ground colour with the dark grounds. */
@Composable
@ReadOnlyComposable
fun sebaroIsDark(): Boolean = LocalSebaroDarkTheme.current
    ?: SebaroTheme.colors.bg.let { it == SebaroDarkColors.bg || it == SebaroWarmDarkColors.bg }

/** The choice in Einstellungen › „Hell oder Dunkel“: follow the system, or always light, or always dark. */
enum class SbThemeMode { System, Light, Dark }

/** The app setting „Bewegung immer reduzieren“ (D46); SebaroAppTheme provides it. */
val LocalSbReduceMotionSetting = staticCompositionLocalOf { false }

/** True when movement is unwanted: the app setting „Bewegung immer reduzieren“ or the system's „Remove animations“. */
@Composable
fun sbReduceMotion(): Boolean = LocalSbReduceMotionSetting.current || rememberSebaroReduceMotion()

/**
 * Root of every sebaro app screen: SebaroTheme with the bundled fonts and no product (D40), text selection in the
 * palette's selection colour, content colour = text, default text style = body. [tone] = the choice „Farbton“
 * (D90, D91 C4c): Warm swaps only the grey roles; cobalt, lime, status colours and tiles stay.
 */
@Composable
fun SebaroAppTheme(
    mode: SbThemeMode = SbThemeMode.System,
    reduceMotion: Boolean = false,
    tone: SebaroTone = SebaroTone.Cool,
    content: @Composable () -> Unit,
) = SebaroAppTheme(mode, reduceMotion, tone, appLocales = null, fallbackMessages = SbMessages.De, content = content)

/** D126: unsupported app locales use the product's fallback (D111 (1)). */
@Composable
fun SebaroAppTheme(
    mode: SbThemeMode = SbThemeMode.System,
    reduceMotion: Boolean = false,
    tone: SebaroTone = SebaroTone.Cool,
    fallbackMessages: SbMessages,
    content: @Composable () -> Unit,
) {
    SebaroAppTheme(mode, reduceMotion, tone, appLocales = null, fallbackMessages = fallbackMessages, content = content)
}

/**
 * D126: [appLocales] mirrors LocaleConfig; match configuration preferences by language, else [fallbackLocale].
 * Null preserves the legacy configuration/table fallback. Custom fallback tables supply their locale explicitly.
 * The two older overloads keep their JVM and default-argument entry points.
 */
// LocalContextResourcesRead: fallback for BOM 2024.12 without LocalResources. AppBundleLocaleChanges: the
// app-locale resources are deliberate; the app disables Play language splits as in §2.3.
@android.annotation.SuppressLint("LocalContextResourcesRead", "AppBundleLocaleChanges")
@Composable
fun SebaroAppTheme(
    mode: SbThemeMode = SbThemeMode.System,
    reduceMotion: Boolean = false,
    tone: SebaroTone = SebaroTone.Cool,
    appLocales: List<Locale>? = null,
    fallbackMessages: SbMessages = SbMessages.De,
    fallbackLocale: Locale = if (fallbackMessages == SbMessages.En) Locale.ENGLISH else Locale.GERMAN,
    content: @Composable () -> Unit,
) {
    val configuration = LocalConfiguration.current
    val configured = configuration.locales
    val matched = if (appLocales == null) null else configured.toLanguageTags().split(',').filter { it.isNotEmpty() }.map(Locale::forLanguageTag)
        .firstOrNull { candidate -> appLocales.any { it.language == candidate.language } }
    val locale = if (appLocales == null) LocalSbAppLocale.current ?: configured[0] else matched ?: fallbackLocale
    val messages = LocalSbMessages.current ?: if (appLocales != null && matched == null) fallbackMessages
        else sbMessagesFor(locale, fallbackMessages)
    val context = LocalContext.current
    val inheritedResources = LocalSbAppResources.current ?: context.resources
    val resources = if (appLocales == null) inheritedResources else remember(context, inheritedResources, locale, configuration) {
        context.createConfigurationContext(Configuration(configuration).apply {
            setLocales(LocaleList(locale))
        }).resources
    }
    val valueMeasures = LocalSbValueMeasureCache.current ?: remember { SbValueMeasureCache() }
    val dark = when (mode) {
        SbThemeMode.System -> isSystemInDarkTheme()
        SbThemeMode.Light -> false
        SbThemeMode.Dark -> true
    }
    SebaroTheme(darkTheme = dark, tone = tone, fonts = SebaroAppFonts) {
        val colors = SebaroTheme.colors
        val selection = remember(colors) {
            TextSelectionColors(handleColor = colors.accent, backgroundColor = colors.selection)
        }
        CompositionLocalProvider(
            LocalSbAppResources provides resources,
            LocalSbAppLocale provides locale,
            LocalSbMessages provides messages,
            LocalSbValueMeasureCache provides valueMeasures,
            LocalSebaroDarkTheme provides dark,
            LocalSbReduceMotionSetting provides reduceMotion,
            LocalTextSelectionColors provides selection,
            LocalContentColor provides colors.text,
            LocalTextStyle provides SebaroTheme.typography.body,
            content = content,
        )
    }
}
